INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('c789f816-ebbe-4759-adfb-69375e6a5118', '21feff02-016d-46e2-bb9d-c27495133b1b', '1. óra: Az év bevezetése, ismétlés, játékos bevezető', 'Éves munkarend, elvárások, játékos feladatok az éves munka elkezdéséhez.', 'Matematika', '6. osztály', 'Év eleji ismétlés, diagnosztika', '[{"id": "5372e8f4-8abd-4b65-930d-ce6913513796", "text": "Mi az éves matematika munka legfőbb célja?", "type": "multiple-choice", "options": [{"id": "7cd6989e-e9a0-4f6d-8395-5004ab320083", "text": "A gondolkodási képesség és matematikai tudás fejlesztése", "isCorrect": true}, {"id": "f4d692dc-87d5-424f-b936-d7444c67262d", "text": "A könyvek visszagyűjtése", "isCorrect": false}, {"id": "3e03e81c-5516-4f4b-80c5-3376630cec26", "text": "Csak a házi feladat írása", "isCorrect": false}, {"id": "8e9c9aa6-634e-4d19-8e00-893d6e768d17", "text": "A számonkérések elkerülése", "isCorrect": false}], "timeLimit": 15}, {"id": "e1fa4fd3-6708-4233-833d-1671586d9c64", "text": "A játékos matematikai feladatok segítik a tanulásra való ráhangolódást.", "type": "true-false", "options": [{"id": "f7849e2c-504d-42d6-af98-b4867ca292f3", "text": "Igaz", "isCorrect": true}, {"id": "2232a03a-783d-4403-848b-0d3ce4dd0a33", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "6b23268f-f7d7-4b4e-877a-df3be26d60a5", "text": "Hány hétből áll egy átlagos magyar tanév?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "36"}, {"id": "4a2cdfde-26af-4b5c-83bb-8fcfb56daaa6", "text": "Melyik állítás ír le helyes tanulási magatartást?", "type": "multiple-choice", "options": [{"id": "a8887727-b7d7-4f7d-bdc1-d4611cd9dd0b", "text": "Rendszeres felkészülés és a hibák megbeszélése", "isCorrect": true}, {"id": "c053b10d-d5ab-4227-b83e-55b2126fdd43", "text": "Minden feladat feladása az első hibánál", "isCorrect": false}, {"id": "4100c71c-2519-4ba6-aa46-a20df868c944", "text": "A füzet otthon hagyása", "isCorrect": false}, {"id": "e9606b0f-a552-492e-b71a-9b89915d0509", "text": "Másolás a padtárstól", "isCorrect": false}], "timeLimit": 15}, {"id": "d43c3573-a760-4dca-aa7a-e96e03c7293c", "text": "Mennyi a 25 + 75 összege?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "100"}, {"id": "11a0a6c7-c471-48e2-9721-6e1eb9204770", "text": "A matematikai órákon a csoportmunka során fontos a kooperáció és egymás segítése.", "type": "true-false", "options": [{"id": "6a57f6a4-b95c-48c3-ab4b-14e1142ec4c2", "text": "Igaz", "isCorrect": true}, {"id": "9f55b591-f490-45b3-9407-0acdf25c34ab", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "a9ffba1f-15a6-4536-bde9-5100acd84b3c", "text": "Mennyi 8 * 9?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "72"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('91b24466-a0e6-44a0-8125-d86e5a6871a8', '21feff02-016d-46e2-bb9d-c27495133b1b', '2. óra: Játékok', 'Játékszabályok, stratégiák, logikai gondolkodás páros és csoportmunkában.', 'Matematika', '6. osztály', 'Év eleji ismétlés, diagnosztika', '[{"id": "c4862993-035f-4cd1-a487-9612c6672cc8", "text": "Mi a stratégiai játékok lényege?", "type": "multiple-choice", "options": [{"id": "4e91b25b-ec37-4b2a-81ff-d5f7d6e8fa8f", "text": "Előre megtervezett lépésekkel a cél elérése", "isCorrect": true}, {"id": "5e15b8d0-3960-451a-bed0-b3d311e5f837", "text": "Kizárólag a szerencsére hagyatkozás", "isCorrect": false}, {"id": "38d37c3e-f153-46fc-a2d7-a51ff0818543", "text": "Kockadobás számolás nélkül", "isCorrect": false}, {"id": "40a5b5d1-d016-483f-aa66-93f67c003699", "text": "A szabályok figyelmen kívül hagyása", "isCorrect": false}], "timeLimit": 15}, {"id": "73ad5fb0-a987-41d0-9c3d-922a0073d023", "text": "A páros és csoportmunka során fontos a csapattársak véleményének meghallgatása.", "type": "true-false", "options": [{"id": "d3fc4421-4733-428d-b9dd-6addec845b7f", "text": "Igaz", "isCorrect": true}, {"id": "afd043bf-26f5-4f11-951f-feaeadf2a217", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "97f86fe1-51ab-45ae-ba70-ed1dd6e5594d", "text": "Hány mezőből áll egy klasszikus 8x8-as sakktábla?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "64"}, {"id": "204552e6-6ba6-4ecf-806e-b513c6f7f1fc", "text": "Melyik játék fejleszti kifejezetten a logikai gondolkodást és a számolást?", "type": "multiple-choice", "options": [{"id": "a887c8bb-17c5-4e6b-af8b-b8a8e43ed70f", "text": "Sudoku", "isCorrect": true}, {"id": "82334068-9386-4acc-a42d-ed353b0445b1", "text": "Fócsoport", "isCorrect": false}, {"id": "506c75e9-8494-460d-90ae-5edc8a84cf49", "text": "Futóverseny", "isCorrect": false}, {"id": "575f99b1-c812-45ac-8355-038b65efad00", "text": "Kő-papír-olló", "isCorrect": false}], "timeLimit": 15}, {"id": "ca2c1a05-96fc-4dd3-b894-b871a6af185b", "text": "A bűvös négyzetben minden sor, oszlop és átló összege megegyezik.", "type": "true-false", "options": [{"id": "fcad6172-0cd2-434a-93de-a1b63585bf3e", "text": "Igaz", "isCorrect": true}, {"id": "08986426-3557-4257-96c9-8f9bcf886069", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "807ba137-5907-4d87-8ad2-4972dd98c565", "text": "Mennyi az 1, 2, 3, 4, 5 számok összege?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "15"}, {"id": "e220e278-d065-47fb-94b9-5e9562a5de9f", "text": "A szabályok betartása elengedhetetlen a fair play játékban.", "type": "true-false", "options": [{"id": "7ce87815-4465-4c50-8bd5-f0f6374d4ac4", "text": "Igaz", "isCorrect": true}, {"id": "61cee807-6546-4f21-8e48-09fb5263ea1b", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('177fcd5d-68f4-451d-bd0e-9415cbdbb06f', '21feff02-016d-46e2-bb9d-c27495133b1b', '3. óra: Év eleji diagnosztikus felmérés', 'Az 5. osztályban tanult ismeretek felmérése, tudásszint diagnosztizálása.', 'Matematika', '6. osztály', 'Év eleji ismétlés, diagnosztika', '[{"id": "a6fb431f-7fff-4d08-adeb-73814f0873a7", "text": "1. Mennyi (-12) + 5?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-7"}, {"id": "93f51622-3e1b-4f34-bf5b-10cdcb612a82", "text": "2. Mennyi 3/4 + 1/4?", "type": "multiple-choice", "options": [{"id": "c1572711-5e4b-4e70-94d6-f804f238bc83", "text": "1 egész (4/4)", "isCorrect": true}, {"id": "7acb28ae-27a9-4bca-ae3e-800bcfaae02a", "text": "2/4", "isCorrect": false}, {"id": "641b3757-9e38-4b58-ba09-a1a33c8f11bf", "text": "4/8", "isCorrect": false}, {"id": "891633b5-9d89-49aa-aad7-017a4970438f", "text": "3/8", "isCorrect": false}], "timeLimit": 15}, {"id": "c09b6029-a60b-4977-a91d-4507d6310735", "text": "3. Mennyi a 4 cm oldalú négyzet kerülete? (cm-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "16"}, {"id": "0a59cb85-2966-406f-805c-0f0efcf600c7", "text": "4. Mennyi a 4 cm oldalú négyzet területe? (cm²-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "16"}, {"id": "554c7da2-9306-4831-976e-678e4d21be03", "text": "5. Hány gramm 2,5 kg?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2500"}, {"id": "fee1fd37-7092-41db-ad0d-ffa043b18e46", "text": "6. A negatív számok a nullától balra találhatók a számegyenesen.", "type": "true-false", "options": [{"id": "e4d3076f-ce51-44d3-a631-a140c5258558", "text": "Igaz", "isCorrect": true}, {"id": "e8d00e5b-6afa-4298-bf0d-7b7b91806e7c", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "ff60d109-1856-4b0d-8ab2-e72ba7df9327", "text": "7. Hány perc 1 és fél óra?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "90"}, {"id": "cee61cff-1d80-4b04-9861-62dfd9181941", "text": "8. Mennyi 0,5 + 0,7?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1.2"}, {"id": "19a62341-04cc-4c60-83ce-7abca91910d5", "text": "9. A derékszögű háromszögnek van egy 90°-os szöge.", "type": "true-false", "options": [{"id": "602e39f5-776b-478a-a95e-55c9b475fc50", "text": "Igaz", "isCorrect": true}, {"id": "a06c9531-6a4e-4541-a277-1b7612c1d065", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "587ec3ba-d7ec-4bad-bea1-3e90e8ea023f", "text": "10. Hány csúcsa van a kockának?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "8"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('6c41a314-d5ad-4762-a942-32672a77e0bd', '21feff02-016d-46e2-bb9d-c27495133b1b', '4. óra: Műveletek az egész számok körében', 'Mit tanultunk ötödik osztályban? A felmérés tapasztalatainak feldolgozása, hibajavítás.', 'Matematika', '6. osztály', 'Egész számok, oszthatóság', '[{"id": "deaa5ad7-69fe-4ed3-b420-b9a56a4f8be5", "text": "Mennyi (-8) + (+15)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "7"}, {"id": "c8991cb6-b724-479a-a99b-f9038fa0e886", "text": "Mennyi (-6) - (+4)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-10"}, {"id": "8784aee6-3a30-403d-96de-47f8848a40c6", "text": "Az ellentett számok összege mindig 0.", "type": "true-false", "options": [{"id": "29a9e85a-ecf1-4eeb-9c38-80396e0c133f", "text": "Igaz", "isCorrect": true}, {"id": "5cec5a18-4b87-45f6-aaf4-0f1739cb0864", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "9a54f54a-a629-4d94-b0d3-ca3a8f46d4b5", "text": "Mennyi |-25| (a -25 abszolút értéke)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "25"}, {"id": "988ae61b-8b72-4394-a73e-1de364b44e6d", "text": "Melyik szám nagyobb: -15 vagy -8?", "type": "multiple-choice", "options": [{"id": "7ce4c4eb-76f1-4e1b-8eea-581c5df85811", "text": "-8", "isCorrect": true}, {"id": "14354f77-b991-443b-bae6-27ebcd8368ac", "text": "-15", "isCorrect": false}, {"id": "de2ab612-9de0-4b14-804b-2e773285cfa8", "text": "Egyenlőek", "isCorrect": false}, {"id": "f61e6c50-7365-43f4-ab3a-bc0a7867ee79", "text": "Nem összehasonlítható", "isCorrect": false}], "timeLimit": 15}, {"id": "f248aefe-82ad-4307-9b77-c8c2971b0b6e", "text": "A nullánál kisebb számokat negatív számoknak nevezzük.", "type": "true-false", "options": [{"id": "90f9b6a7-0e16-41bf-aa54-4e0245ffd32b", "text": "Igaz", "isCorrect": true}, {"id": "cccae701-aa73-4945-8c8b-9e4d87c9fb14", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "20e28658-deba-4ca3-9f33-6bef2422a108", "text": "Mennyi (-10) + (-5)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-15"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('8471e65a-8d87-4868-91e3-b3312eb38007', '21feff02-016d-46e2-bb9d-c27495133b1b', '5. óra: Az egész számok szorzása', 'Negatív számokkal való szorzás, az előjelszabály megértése és alkalmazása.', 'Matematika', '6. osztály', 'Egész számok, oszthatóság', '[{"id": "112dca65-67cf-4424-b2fb-83be586f8a25", "text": "Mi az előjelszabály két negatív szám szorzásakor? (- * -)", "type": "multiple-choice", "options": [{"id": "98a94645-3021-4b87-b7d3-1a72301b9a82", "text": "Pozitív (+)", "isCorrect": true}, {"id": "9e551daf-3716-4562-8e0d-e25d3ab8d734", "text": "Negatív (-)", "isCorrect": false}, {"id": "60cc390d-f3ac-4524-a3bb-e971a1ab9177", "text": "Mindig 0", "isCorrect": false}, {"id": "19b9d979-513c-4a5d-9e54-3608eb4f451f", "text": "Nem lehet megszorozni", "isCorrect": false}], "timeLimit": 15}, {"id": "2b3de12d-9f9b-4473-9119-4acc6df9512e", "text": "Mennyi (-4) * (+5)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-20"}, {"id": "af693647-66ae-4dfe-86e9-8b616c1a8738", "text": "Mennyi (-6) * (-7)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "42"}, {"id": "82c19eef-947e-49b1-9c4a-d263e119e575", "text": "Egy pozitív és egy negatív szám szorzata mindig negatív.", "type": "true-false", "options": [{"id": "316b1210-5e38-4257-aaf2-0ce997e7771e", "text": "Igaz", "isCorrect": true}, {"id": "6350232b-e927-4ca7-90a6-4d218fa61e4d", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "234b3951-66c9-47f9-8363-9757bc726509", "text": "Mennyi (-3) * 0?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "0"}, {"id": "8072dc2a-7681-4c0a-8b83-835a406723c9", "text": "Ha három negatív számot szorzunk össze, a szorzat előjele negatív lesz.", "type": "true-false", "options": [{"id": "cf197f29-a7fb-4d4c-a74c-6797943da60e", "text": "Igaz (- * - * - = -)", "isCorrect": true}, {"id": "7ebca144-6b7a-409a-bd27-e7293c520203", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "30500084-a967-432c-a6e9-66c801380e8e", "text": "Mennyi (-2) * (-3) * (-4)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-24"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('de0483fe-bfe5-4f6f-843f-336dd2f6d137', '21feff02-016d-46e2-bb9d-c27495133b1b', '6. óra: Gyakorlóóra: az egész számok szorzása', 'Több tényező előjelének meghatározása, szorzások gyakorlása.', 'Matematika', '6. osztály', 'Egész számok, oszthatóság', '[{"id": "7bdd6573-a4ce-4dcd-b7d1-73bc2fcf8574", "text": "Mennyi (-5) * (-2) * (+3)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}, {"id": "3a2540cb-7f08-4754-8506-0a6fe1dc7c3e", "text": "Ha egy szorzatban páros számú negatív tényező van, a szorzat előjele:", "type": "multiple-choice", "options": [{"id": "10135014-e327-45c7-ac1d-f1ec4583d5ce", "text": "Pozitív", "isCorrect": true}, {"id": "9801d3bb-de86-44be-8e2b-17699f76f947", "text": "Negatív", "isCorrect": false}, {"id": "7e4b135a-5ef7-436d-af5a-0e001c0b0798", "text": "Nulla", "isCorrect": false}, {"id": "4dac197f-1ece-4be2-8008-363f7b0749b5", "text": "Változó", "isCorrect": false}], "timeLimit": 15}, {"id": "4a918fd9-c50a-450e-9733-da0d66f8deec", "text": "Mennyi (-10) * (-10)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "100"}, {"id": "704f5cac-2c66-44fd-9523-542fd7659526", "text": "A 0-val való szorzás eredménye mindig 0.", "type": "true-false", "options": [{"id": "d554bec1-f89a-4d50-8c22-32e0f87919a9", "text": "Igaz", "isCorrect": true}, {"id": "1e730fcc-9d65-4852-9cac-e22dca270423", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "b883f7d5-0515-456f-83e2-388d7b4a3857", "text": "Mennyi (-1) * (+15)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-15"}, {"id": "ce2f6089-6f9f-4be9-aa97-5b7830869bd1", "text": "Mennyi a (-2) köbe ( (-2) * (-2) * (-2) )?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-8"}, {"id": "ed0da368-e5f5-4666-8e2e-133e472fdfb1", "text": "Az írásbeli szorzáskor az előjelet a művelet végzésétől függetlenül, az előjelszabály szerint állapítjuk meg.", "type": "true-false", "options": [{"id": "62789279-97c1-42c3-9b1e-9785658c638e", "text": "Igaz", "isCorrect": true}, {"id": "8c58e570-409b-4c2e-afa5-52b56c3a0baf", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('4c300a79-b438-4688-be7c-75f0d5cc3bea', '21feff02-016d-46e2-bb9d-c27495133b1b', '7. óra: Az egész számok osztása', 'Negatív osztandó, osztóval végzett műveletek algoritmusa, előjelszabály osztásnál.', 'Matematika', '6. osztály', 'Egész számok, oszthatóság', '[{"id": "79b41959-661d-4731-9ee3-2f80be175ac1", "text": "Mi az előjelszabály egész számok osztásakor?", "type": "multiple-choice", "options": [{"id": "60f67a97-39d8-4c0c-81ab-281d1cdb44d6", "text": "Ugyanaz, mint a szorzásnál (+:+=+, -:-=+, +:-=-, -:+=-)", "isCorrect": true}, {"id": "c6cb377f-c66d-428e-955f-e1b864912630", "text": "Mindig negatív", "isCorrect": false}, {"id": "fe1fd57b-6b29-4d94-a4d2-d0f6f7ad18e4", "text": "Mindig pozitív", "isCorrect": false}, {"id": "45cef00e-ba37-4981-9bde-db59ff99f3e2", "text": "Kivonást kell végezni", "isCorrect": false}], "timeLimit": 15}, {"id": "b82c32c0-b011-4dd2-9246-6c58fb855d94", "text": "Mennyi (-20) : (+4)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-5"}, {"id": "13f0d361-be5b-4f01-b9d2-25cd6c8078c7", "text": "Mennyi (-36) : (-6)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "47ba84c3-6e1f-42e1-9b7d-0fe874ca7ce0", "text": "Nullával osztani nem lehet a matematikában.", "type": "true-false", "options": [{"id": "3726aa50-9eeb-4b6b-95da-6ece21362eec", "text": "Igaz", "isCorrect": true}, {"id": "e4635b86-01ff-4c01-9f46-b7dbc32c542c", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "ad636d6b-fd45-4df2-bb9d-27bf0f1bfd48", "text": "Mennyi (+50) : (-5)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-10"}, {"id": "95cc9d8c-64d5-4504-abcb-7c2189090019", "text": "Ha a (-15)-öt elosztjuk (-3)-mal, az eredmény pozitív szám.", "type": "true-false", "options": [{"id": "72b0de09-426e-48c4-8a08-091614645f01", "text": "Igaz", "isCorrect": true}, {"id": "1526bcd7-c674-4732-b479-46979e66a348", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "e7cba956-1b3f-4778-99b9-7c45e4a3d3e5", "text": "Mennyi 0 : (-8)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "0"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('ac2cdc07-03a7-4f87-9f44-18cad40367f6', '21feff02-016d-46e2-bb9d-c27495133b1b', '8. óra: Az egész számok osztásának gyakorlása', 'Írásbeli és fejben osztás gyakorlása negatív és pozitív számokkal.', 'Matematika', '6. osztály', 'Egész számok, oszthatóság', '[{"id": "0c6c2211-6180-48be-b7dc-071909b60ca0", "text": "Mennyi (-100) : (-25)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "ebb2b41a-47d1-414e-a1c6-51ef9230a19a", "text": "Mennyi (-48) : (+8)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-6"}, {"id": "e78d238e-3922-4bac-976a-852c059ae634", "text": "Melyik egyenlet helyes?", "type": "multiple-choice", "options": [{"id": "e8933829-5037-497d-8c27-1701d8106735", "text": "(-18) : (-3) = 6", "isCorrect": true}, {"id": "29b6a836-bc52-4180-b398-bc61d07536f4", "text": "(-18) : (-3) = -6", "isCorrect": false}, {"id": "25d89a94-4932-4ab0-b611-4696879f8b53", "text": "(-18) : (+3) = 6", "isCorrect": false}, {"id": "745e21be-636f-43c9-9ce1-cf08e685d73b", "text": "(+18) : (-3) = 6", "isCorrect": false}], "timeLimit": 15}, {"id": "ef547dda-72a3-4055-98d6-a383c69d4cbf", "text": "A hányados ellenőrzése szorzással történik.", "type": "true-false", "options": [{"id": "2da3beb7-e885-4705-965a-36335a8dd3da", "text": "Igaz", "isCorrect": true}, {"id": "ade57aa1-0da7-4089-a125-54f76bc0d9a2", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "44303960-fcc2-4636-8f12-ca67b3bfb3af", "text": "Mennyi (-81) : (+9)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-9"}, {"id": "5e91e2c2-fe69-4938-811e-87846560ab4a", "text": "Ha két szám hányadosa pozitív, a két szám előjele azonos.", "type": "true-false", "options": [{"id": "7be8f024-58a8-44c9-8d39-d306e161d434", "text": "Igaz", "isCorrect": true}, {"id": "92abcd92-d8eb-4dc2-a8d3-c43047fd30cd", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "cf2111e0-386c-49a3-a5b1-4fb292f57d12", "text": "Mennyi (-144) : (-12)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "12"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('0e65f9ab-4df7-4512-9a6e-41cb92876484', '21feff02-016d-46e2-bb9d-c27495133b1b', '9. óra: Hány eset van? Számoljuk össze!', 'Összeszámlálás fagráffal (ágrajz), táblázattal, rendszerezett felsorolással.', 'Matematika', '6. osztály', 'Egész számok, oszthatóság', '[{"id": "0d88db88-9b05-4f51-b11b-5e651f367101", "text": "Milyen eszközt használhatunk az összes lehetőség rendszerezett szemléltetésére?", "type": "multiple-choice", "options": [{"id": "08f92ba9-1c72-49ec-b288-ec986d71dc23", "text": "Fagráfot (ágrajzot) és táblázatot", "isCorrect": true}, {"id": "f6ce5eab-51e4-4785-8379-835a9362cad0", "text": "Szögmérőt", "isCorrect": false}, {"id": "8cb7dd70-ce97-4b76-8487-436c361fbf0f", "text": "Körzőt", "isCorrect": false}, {"id": "34a0c5cc-93ef-4a81-8a87-8640b37671cb", "text": "Vonalzót", "isCorrect": false}], "timeLimit": 15}, {"id": "a6d303ee-a764-425b-aed0-700c1f422718", "text": "Hányféleképpen ülhet le 2 gyerek (Peti és Kati) két egymás melletti székre?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}, {"id": "a7c6f6c4-de76-4399-a861-971fc3b7030a", "text": "Hány különböző 2 jegyű szám képezhető az 1 és 2 számjegyekből (számjegyismétléssel)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "36a9656b-f45f-423b-bc81-4b6adcfaa253", "text": "A rendszerezett felsorolás segít abban, hogy egyetlen lehetőséget se hagyjunk ki.", "type": "true-false", "options": [{"id": "978de7b1-c619-4a79-95cd-078945c876eb", "text": "Igaz", "isCorrect": true}, {"id": "8bbe1b8b-0cd6-46af-bf7c-14f1d5e5f7a3", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "de383c33-d4eb-4aba-b98f-25857f7dc6c9", "text": "Hányféleképpen választhatunk ki 3 póló és 2 nadrág közül egy ruhakészletet?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "fbdc3144-bdda-4e49-b02c-e64e3df879d8", "text": "A kombinatorikai feladatoknál a sorrend mindig számít.", "type": "true-false", "options": [{"id": "f4e499c4-562a-4ccf-899d-7e48a5cc1af3", "text": "Igaz", "isCorrect": false}, {"id": "c8f2b518-d73f-4321-ab55-1f8b6aa600f8", "text": "Hamis (van ahol számít, van ahol nem)", "isCorrect": true}], "timeLimit": 15}, {"id": "af92b95e-7ac3-4338-9c21-3785d09f53e2", "text": "Hány lapja van egy érmének (kimenetelek száma)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('25c53a8f-6ac9-4332-8731-3dc58509a86d', '21feff02-016d-46e2-bb9d-c27495133b1b', '10. óra: Gyakorlóóra. Hány eset van? Számoljuk össze!', 'Összeszámlálási feladatok gyakorlása fagráffal és táblázattal.', 'Matematika', '6. osztály', 'Egész számok, oszthatóság', '[{"id": "cdba2fe6-3a7b-405a-8e3d-47596a18af80", "text": "Hány 2 jegyű páros szám képezhető az 1, 2, 3 számjegyekből (számjegyismétlés nélkül)?", "type": "multiple-choice", "options": [{"id": "18fc4a05-a36a-4377-a93c-b08debe72491", "text": "2 (12, 32)", "isCorrect": true}, {"id": "c41b0e30-a75e-4a09-888c-dac780ba3cae", "text": "3", "isCorrect": false}, {"id": "4b09bff2-d29c-4eee-a5d5-7b50368808d9", "text": "4", "isCorrect": false}, {"id": "8caebf7c-a901-46f1-a8af-946fc426ee09", "text": "6", "isCorrect": false}], "timeLimit": 15}, {"id": "13610faf-57fc-46a5-8457-3c98977494ef", "text": "Három barát köszöntésekor (mindenki mindenkivel kezet fog) hány kézfogás történik?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "3"}, {"id": "27a2c9c7-7b80-40b4-bb35-872a8eee6ea9", "text": "A fagráf ágai az egyes döntési lépéseket ábrázolják.", "type": "true-false", "options": [{"id": "c67a5df5-facd-44a5-a263-fd2f46650333", "text": "Igaz", "isCorrect": true}, {"id": "c3b04972-4317-4962-9513-adbb43c3f397", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "d52d313e-6542-4bcf-85a3-cbbe8fbf7c17", "text": "Hány különböző sorrendben futhat be a célba 3 versenyző (A, B, C)? (3! = 3*2*1)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "b5f0473b-aa13-4589-a7fe-0a928839f4f7", "text": "Ha 4 csapat játszik körmérkőzést (mindenki mindenkivel egyszer), hány mérkőzést játszanak összesen?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "f0b1d128-b718-40e2-a437-e2a91fea8e8d", "text": "Egy szabályos dobókocka eldobásakor 6-féle kimenetel lehetséges.", "type": "true-false", "options": [{"id": "5988cf52-360d-41de-8ead-4a7ab6781e3e", "text": "Igaz", "isCorrect": true}, {"id": "535474e4-0e8c-4207-837d-eb70a414419c", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "76016e3c-07be-43a3-920d-697d2fc25d64", "text": "Hány kétjegyű szám képezhető a 0 és 5 számjegyekből (0 nem lehet az első számjegy)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('2c65b67d-7750-4f80-82af-1088a95fcebc', '21feff02-016d-46e2-bb9d-c27495133b1b', '11. óra: Összeszámlálási feladatok megoldása', 'Önálló feladatmegoldás rendszerezett felsorolással és faábrával.', 'Matematika', '6. osztály', 'Egész számok, oszthatóság', '[{"id": "6320cf6e-4a7d-4dfe-b296-1f095efa78bd", "text": "Hányféleképpen rakhatunk sorba 4 különböző könyvet a polcon? (4*3*2*1)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "24"}, {"id": "5a8ccd44-5e3c-4f12-bff8-83e1f02ee780", "text": "Hány 3 jegyű szám képezhető a 7, 8, 9 számjegyekből ha mindegyiket csak egyszer használhatjuk fel?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "a15e067c-115c-4710-92fa-cc23cfa90c64", "text": "Az ágrajz utolsó szintjén lévő levelek száma megadja az összes lehetséges kimenetelt.", "type": "true-false", "options": [{"id": "9dde5b99-6c51-4161-b647-4185fc8e415d", "text": "Igaz", "isCorrect": true}, {"id": "ffc372f5-6afa-450c-b9b9-fd7851df823c", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "26ab6e57-7e16-4356-90cf-f995d39cb960", "text": "Melyik állítás igaz a valószínűségi kísérletekre?", "type": "multiple-choice", "options": [{"id": "8b8d45c4-9286-4544-bfdd-88afb8660e05", "text": "A lehetséges esetek száma a kedvező és kedvezőtlen esetek összege", "isCorrect": true}, {"id": "4f4ef5f9-cc01-4465-83f8-45b06e4f087c", "text": "Mindig csak 1 eset lehetséges", "isCorrect": false}, {"id": "36a09421-0a8f-4334-bb55-a8c148e32b05", "text": "Sohasem lehet kiszámolni az esetek számát", "isCorrect": false}, {"id": "877e7dd1-8824-4764-adf2-23eb28bdd206", "text": "Csak páros szám lehet az eredmény", "isCorrect": false}], "timeLimit": 15}, {"id": "b083ed36-f3ea-4764-8a63-0f85b7a7c02d", "text": "Hányféle kétgombócos fagyit választhatunk 3-féle ízből, ha két különböző ízt kérünk?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "3"}, {"id": "1487511e-09fd-4281-804b-c77e45b8d9b7", "text": "Ha egy feldobott pénzérmét kétszer dobunk fel egymás után, a lehetséges kimenetelek száma 4.", "type": "true-false", "options": [{"id": "c35a1f51-d425-499f-8d15-2c29f354b0d2", "text": "Igaz (FF, FI, IF, II)", "isCorrect": true}, {"id": "46b2362a-1c49-4ae2-ae8f-423e7ac29569", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "23809430-c2ae-4dbc-a98f-945c75a74340", "text": "Hány válaszlehetőség van egy 4 opciós feleletválasztós kérdésnél?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('50c900b1-a718-45a9-9b6d-6d6c7b431f60', '21feff02-016d-46e2-bb9d-c27495133b1b', '12. óra: Számonkérés', 'Az egész számok műveleteiből és az összeszámlálásból tanultak számonkérése (10 kérdés).', 'Matematika', '6. osztály', 'Egész számok, oszthatóság', '[{"id": "d8963dee-86df-4c96-9e1b-4cf01b0c0d52", "text": "1. Mennyi (-15) + (+20)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5"}, {"id": "75c9a1a9-cab6-4997-9c85-f4ea42bd6907", "text": "2. Mennyi (-6) * (-8)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "48"}, {"id": "62a28854-817a-40fb-9a23-262d1d4d956a", "text": "3. Mennyi (-54) : (+9)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-6"}, {"id": "f16ca1e5-da1e-405d-9969-1e90b63dc278", "text": "4. Melyik szám abszolút értéke nagyobb: |-30| vagy |+20|?", "type": "multiple-choice", "options": [{"id": "ff5d0c65-f81e-4a79-861f-cf2dc896e54b", "text": "|-30|", "isCorrect": true}, {"id": "0d36927a-0300-42f5-9dbe-65ffbdec3af3", "text": "|+20|", "isCorrect": false}, {"id": "f82af53e-6c34-4829-951b-24656d7ac488", "text": "Egyenlőek", "isCorrect": false}, {"id": "4e3b6ca2-5448-4590-9463-cbee3f159a81", "text": "Egyik sem", "isCorrect": false}], "timeLimit": 15}, {"id": "eb68e576-b80f-488b-ae87-edd532e34a68", "text": "5. Mennyi (-3) * (-2) * (-5)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-30"}, {"id": "3c7f7920-9996-4e13-87c3-68bc2abc41e1", "text": "6. A negatív szám szorzása negatív számmal pozitív eredményt ad.", "type": "true-false", "options": [{"id": "c0e8fd82-43e6-484e-bade-ea6840c741f0", "text": "Igaz", "isCorrect": true}, {"id": "eb6cbbac-1da7-42fe-b3bb-f6814137b4ad", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "33a545c0-38d0-4df4-b974-1bfed3bb035f", "text": "7. Hány különböző sorrendben ülhet le 3 gyerek egy padra?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "6018968b-6583-4be1-a478-f790cbfcdc19", "text": "8. Mennyi (-40) : (-8)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5"}, {"id": "e7ebcc4f-7a7b-4b4b-b9af-faf11d100595", "text": "9. A nullának nincs ellentettje (vagy önmaga az ellentettje).", "type": "true-false", "options": [{"id": "8073997d-c4b0-47f3-ac46-61b11e221bd7", "text": "Igaz", "isCorrect": true}, {"id": "81d810c0-cef1-42cf-85d7-2b01e74146c9", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "5a9de60f-3f9d-44fd-a5ec-fc95c06034be", "text": "10. Mennyi (-10) + (-20) - (-15)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-15"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('c579225d-2ed0-4bdf-aa24-e6ec874a82d7', '21feff02-016d-46e2-bb9d-c27495133b1b', '13. óra: Osztó, többszörös', 'Osztó, többszörös fogalma, osztópárok meghatározása.', 'Matematika', '6. osztály', 'Egész számok, oszthatóság', '[{"id": "9211d9e2-21be-4f9f-abf6-75192801dc56", "text": "Mit nevezünk egy ''a'' természetes szám osztójának?", "type": "multiple-choice", "options": [{"id": "5bd5ba55-c4a6-4759-99d5-802a44556156", "text": "Azt a ''b'' számot, amellyel ''a''-t elosztva a maradék 0", "isCorrect": true}, {"id": "03efa5f0-2e73-4186-823c-6625b87664e6", "text": "Azt a számot, amit ''a''-hoz hozzáadunk", "isCorrect": false}, {"id": "285a816d-e776-4f85-a539-6756a0b6e5a5", "text": "Azt a számot, ami nagyobb ''a''-nál", "isCorrect": false}, {"id": "59911599-0d88-4601-ab67-a8188d72fa74", "text": "Minden páratlan számot", "isCorrect": false}], "timeLimit": 15}, {"id": "2396a4fb-30fc-441e-ad3a-5e3a241c24cd", "text": "Az 1 minden természetes számnak osztója.", "type": "true-false", "options": [{"id": "912fc50b-4572-4eac-9266-f09c28871bb5", "text": "Igaz", "isCorrect": true}, {"id": "8aa3f57d-1c3c-4ccc-938f-b5239e986de7", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "d9fa37ca-1b1b-4d30-b248-666d442cb3ed", "text": "Hány osztója van a 12-nek? (1, 2, 3, 4, 6, 12)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "1ad42622-f092-44f7-a74f-3ea9f4ee4690", "text": "Melyik szám a 15 többszöröse az alábbiak közül?", "type": "multiple-choice", "options": [{"id": "7fd7df31-b618-4f5c-8ddd-6395bbbcdc0d", "text": "45", "isCorrect": true}, {"id": "e42ddc8b-b36a-42f6-b48d-2a7c3921cb8b", "text": "5", "isCorrect": false}, {"id": "f66ecbf1-f67d-4828-8a12-d8e014fa360e", "text": "3", "isCorrect": false}, {"id": "7f1accf3-351f-4467-a742-9587dac57358", "text": "10", "isCorrect": false}], "timeLimit": 15}, {"id": "263e7c0b-0294-48ed-99e4-113984830de1", "text": "Minden számnak végtelen sok többszöröse van.", "type": "true-false", "options": [{"id": "f8d55386-b705-47e5-904e-821bb9f30c85", "text": "Igaz", "isCorrect": true}, {"id": "e3d79335-c0b5-48a8-a9ed-8afec05d538b", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "c3f24d9b-d5d9-4d6b-b7bf-64bc00e4d82d", "text": "Mi a 20 legkisebb pozitív osztója?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}, {"id": "41239534-ba37-4ff3-93cd-472ff0e65b95", "text": "Mi a 20 legnagyobb osztója önmagán kívül?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('be6b7d19-fdcb-4f4e-a752-74d2a786d92a', '21feff02-016d-46e2-bb9d-c27495133b1b', '14. óra: Számolás maradékokkal', 'Az osztási maradék fogalma, paritás vizsgálata, összeg maradéka.', 'Matematika', '6. osztály', 'Egész számok, oszthatóság', '[{"id": "010267ed-d7e0-4d05-9e23-013b6710bcfd", "text": "Mennyi a maradék, ha 23-at elosztjuk 5-tel? (23 = 4*5 + 3)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "3"}, {"id": "1ff77356-3a7d-44bb-a94a-817b5c42ca16", "text": "Egy számot 4-gyel elosztva a lehetséges maradékok: 0, 1, 2, 3.", "type": "true-false", "options": [{"id": "9f70d7a4-1177-49a2-8763-4e6f37388f23", "text": "Igaz", "isCorrect": true}, {"id": "92177d1f-b935-40fd-8d9d-a9b97c3a909d", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "91a60dca-a95c-4b4e-b62b-d027a6949898", "text": "Milyen maradékot ad 2-vel osztva minden páratlan szám?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}, {"id": "38e9242c-6f3c-49b3-8f40-a8cb0779445d", "text": "Két páratlan szám összege mindig páros szám.", "type": "true-false", "options": [{"id": "e92cb7ff-51e0-4cc7-a37a-b562e5a83844", "text": "Igaz (páratlan + páratlan = páros)", "isCorrect": true}, {"id": "485267ff-af50-473a-9b7a-34e2ac872bfc", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "42a60ed7-11de-4805-ae67-58e12974e432", "text": "Mennyi a maradék 37 : 10 esetén?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "7"}, {"id": "e3a76a41-2635-45cb-86bc-61c1b1ba6bf7", "text": "Két páros szám szorzata mindig páros szám.", "type": "true-false", "options": [{"id": "3ea191bc-9cc5-48dd-9b28-256debdd9a4f", "text": "Igaz", "isCorrect": true}, {"id": "6c2e3708-651f-488b-915b-04acfabe36f6", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "c2eaa19b-0e0b-4aa9-a5e1-f42678a699b7", "text": "Melyik szám ad 0 maradékot 3-mal osztva?", "type": "multiple-choice", "options": [{"id": "2afdaad2-4c3e-4431-b6d9-8a27e286fcb1", "text": "15", "isCorrect": true}, {"id": "413cb87e-cec4-4518-824b-8c70755acdaf", "text": "16", "isCorrect": false}, {"id": "7204f6d7-be6c-4c5b-8288-bc6c4b9f2add", "text": "17", "isCorrect": false}, {"id": "c302bd82-2214-4ab0-b33b-1361e246533b", "text": "19", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('b57d171f-60aa-4060-a907-712025ee73f7', '21feff02-016d-46e2-bb9d-c27495133b1b', '15. óra: Hány osztója van?', 'Természetes számok csoportosítása osztóik száma alapján, prímek és összetett számok.', 'Matematika', '6. osztály', 'Egész számok, oszthatóság', '[{"id": "6cedca7c-3278-456c-8b8c-ba700d8f83be", "text": "Hogyan nevezzük azokat a számokat, amelyeknek pontosan 2 osztójuk van (1 és önmaga)?", "type": "multiple-choice", "options": [{"id": "7a6a736b-d5ce-4dfd-bd67-f8f8168ec18d", "text": "Prímszámok (prímek)", "isCorrect": true}, {"id": "88ac9884-e9d0-4720-93d5-4b10f5ad40a7", "text": "Összetett számok", "isCorrect": false}, {"id": "8c40396f-4e73-4c40-87f6-b73dc46b3410", "text": "Páros számok", "isCorrect": false}, {"id": "387092c2-0ec3-4547-9a53-5ac20ace140c", "text": "Negatív számok", "isCorrect": false}], "timeLimit": 15}, {"id": "13821627-a393-406d-b8c5-41f6d269a1fa", "text": "Az 1 prímszám.", "type": "true-false", "options": [{"id": "864ecc8b-5577-4fa0-9e66-3e10c5ea386a", "text": "Igaz", "isCorrect": false}, {"id": "cfb248ef-2bf6-4db3-abfe-70943d4de1c5", "text": "Hamis (az 1 sem nem prím, sem nem összetett)", "isCorrect": true}], "timeLimit": 15}, {"id": "362f4c3c-1cb6-44c4-bf6d-a38bfd7726a4", "text": "Melyik a legkisebb prímszám?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}, {"id": "d314b3e0-8733-4eb2-84ed-76bd25e2ff3b", "text": "Melyik az egyetlen páros prímszám?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}, {"id": "9a1ca11a-ef55-46e8-a515-baa18693ab53", "text": "Azokat a számokat, amelyeknek 2-nél több osztójuk van, összetett számoknak nevezzük.", "type": "true-false", "options": [{"id": "b33229bd-260e-4d15-b448-bdb978889efe", "text": "Igaz", "isCorrect": true}, {"id": "e138bd8a-e22e-41eb-9a11-71a39f826424", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "a267cf01-a8ef-433f-8f84-dacc5a00f9ad", "text": "Hány osztója van a 7-nek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}, {"id": "2f6f2881-ca89-46f0-824c-18aa6ffa2fe2", "text": "Melyik prím az alábbiak közül?", "type": "multiple-choice", "options": [{"id": "1fbb4b22-108b-40ea-942e-727adacbc23e", "text": "13", "isCorrect": true}, {"id": "d76d75af-866d-4cc0-b94d-9c1295c36910", "text": "9", "isCorrect": false}, {"id": "f555faa5-2c81-4092-9217-0081d84ab1f6", "text": "15", "isCorrect": false}, {"id": "8bd3febb-7eaa-42a0-ae02-e8ce1ae6b499", "text": "21", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('d71f848f-0c1e-4137-bbe6-a36cc63ba42a', '21feff02-016d-46e2-bb9d-c27495133b1b', '16. óra: Feladatok az osztók számának meghatározására, számolás maradékokkal', 'Szöveges feladatok az osztókról és maradékokról.', 'Matematika', '6. osztály', 'Egész számok, oszthatóság', '[{"id": "095a9dcf-b1a9-4884-b217-c89e5dce52a3", "text": "Hány osztója van a 9-nek? (1, 3, 9)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "3"}, {"id": "99f77701-f35e-41e6-b89c-c58d975746c5", "text": "A négyzetszámoknak páratlan számú osztójuk van.", "type": "true-false", "options": [{"id": "7585f742-aa3d-448d-9745-76798e72040c", "text": "Igaz (pl. 9-nek 3 osztója van: 1, 3, 9)", "isCorrect": true}, {"id": "705e7ee4-ee12-4c57-9028-118715f43b21", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "369a2ac7-160b-4858-a2a4-c8af59860375", "text": "Ha 25 alma van és 4 gyerek között egyenlően elosztjuk, hány alma marad a kosárban?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}, {"id": "6ac6f920-e89f-4d75-9883-96164f9ba2c9", "text": "Hány prímszám van 10 és 20 között? (11, 13, 17, 19)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "811f1f77-1293-475c-965b-11b90e423516", "text": "Melyik szám összetett szám az alábbiak közül?", "type": "multiple-choice", "options": [{"id": "fe0c7fde-4831-4fca-b1f8-48c1a36a68fd", "text": "27 (osztói: 1,3,9,27)", "isCorrect": true}, {"id": "b71ec59a-69f4-4ba4-85a2-9b4fd3fb5f60", "text": "23", "isCorrect": false}, {"id": "74de8415-777a-41c6-a0f7-5753cb0c778a", "text": "29", "isCorrect": false}, {"id": "22624c91-1705-44f1-a020-07481118c076", "text": "31", "isCorrect": false}], "timeLimit": 15}, {"id": "68a1e8fe-53ec-4c7e-afca-90c66b6e68eb", "text": "Minden páratlan szám prímszám.", "type": "true-false", "options": [{"id": "cd980e44-5dc8-4b86-a411-2b42483a0e85", "text": "Igaz", "isCorrect": false}, {"id": "8da0c64e-4116-4113-8851-3d98ffb7b5e5", "text": "Hamis (pl. 9, 15, 21 nem prím)", "isCorrect": true}], "timeLimit": 15}, {"id": "26ca3b11-9081-4c8e-a0c5-186e7dafb27c", "text": "Mennyi a legkisebb kétjegyű prímszám?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "11"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('b5112d00-aeae-4f0f-91ee-44fac44e7040', '21feff02-016d-46e2-bb9d-c27495133b1b', '17. óra: Oszthatóság 2-vel, 5-tel, 10-zel', 'Oszthatósági szabályok az utolsó számjegy alapján.', 'Matematika', '6. osztály', 'Egész számok, oszthatóság', '[{"id": "c42c37af-9f4b-4406-9293-3347ca10b7e4", "text": "Mikor osztható egy szám 2-vel?", "type": "multiple-choice", "options": [{"id": "a9d8927f-0c54-49bd-9e3b-b297f05b9593", "text": "Ha az utolsó számjegye páros (0, 2, 4, 6, 8)", "isCorrect": true}, {"id": "2b583d4c-a9da-4cd6-9e20-2315895581ec", "text": "Ha a számjegyek összege 2", "isCorrect": false}, {"id": "42c15a5b-a14a-43eb-afa4-1a96002c87fe", "text": "Ha 5-re végződik", "isCorrect": false}, {"id": "423442db-e645-43ef-bb36-5916ec0e574d", "text": "Minden szám osztható 2-vel", "isCorrect": false}], "timeLimit": 15}, {"id": "6e4c9846-494d-4b12-8fe4-0bc6f1abc041", "text": "Mikor osztható egy szám 5-tel?", "type": "multiple-choice", "options": [{"id": "0da7dde5-11f7-4cdc-b32a-75a99b88796f", "text": "Ha az utolsó számjegye 0 vagy 5", "isCorrect": true}, {"id": "352f64b3-9732-4290-8f34-e0ccc6930dbb", "text": "Ha 2-re végződik", "isCorrect": false}, {"id": "d92d6620-3572-4bda-b6be-a69b40483529", "text": "Ha páratlan", "isCorrect": false}, {"id": "0ae49a43-d7e4-49d4-899c-3379137ce81e", "text": "Ha a számjegyek összege 5", "isCorrect": false}], "timeLimit": 15}, {"id": "cd4c0bf5-3a56-4cad-8e92-ea2ebb1c688f", "text": "Mikor osztható egy szám 10-zel?", "type": "multiple-choice", "options": [{"id": "81014481-e3ab-4cfb-90f8-8f5df9bf293e", "text": "Ha az utolsó számjegye 0", "isCorrect": true}, {"id": "521b5553-fd4b-4c89-a7df-a8d7a547c71c", "text": "Ha az utolsó számjegye 5", "isCorrect": false}, {"id": "0522e6da-9205-4ac8-868f-5226a148bb5e", "text": "Ha páros", "isCorrect": false}, {"id": "111df52c-e1df-47ca-960d-f2538398fbb9", "text": "Ha 10 számjegyből áll", "isCorrect": false}], "timeLimit": 15}, {"id": "1bf22839-108b-4867-b090-adcdfebf3ba3", "text": "A 435 osztható 5-tel.", "type": "true-false", "options": [{"id": "22e0a37b-59af-43cc-91e4-9fc7d0c7838d", "text": "Igaz", "isCorrect": true}, {"id": "dadc5346-eae7-4143-9a74-4ef1c3bb4d0d", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "80a40219-4a98-45e5-ad15-67efc1997382", "text": "A 680 osztható 2-vel, 5-tel és 10-zel is.", "type": "true-false", "options": [{"id": "da6360d9-9df0-46d4-82cd-058d3471fb44", "text": "Igaz", "isCorrect": true}, {"id": "ec4409a7-8d4d-41b0-9513-b31ed83511f9", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "3f82319f-d685-412b-a612-acde787c821e", "text": "Osztható-e a 789 2-vel?", "type": "true-false", "options": [{"id": "b862d334-305f-4abe-963e-ae4fb5d789a3", "text": "Igaz", "isCorrect": false}, {"id": "9b3fc39e-2501-481b-95a7-370ae035ccc7", "text": "Hamis (páratlanra végződik)", "isCorrect": true}], "timeLimit": 15}, {"id": "ecdf0476-0bfa-4b4b-a3be-a2b64ee25559", "text": "Melyik számjegy állhat a 45_ végén, hogy a szám osztható legyen 10-zel?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "0"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('7413be75-dcc1-4211-b662-b06123020932', '21feff02-016d-46e2-bb9d-c27495133b1b', '18. óra: Oszthatóság 3-mal és 9-cel', 'A számjegyek összegén alapuló oszthatósági szabályok.', 'Matematika', '6. osztály', 'Egész számok, oszthatóság', '[{"id": "0ba66083-dfaf-4363-94a8-c84587e32135", "text": "Mikor osztható egy szám 3-mal?", "type": "multiple-choice", "options": [{"id": "3921d885-28b8-4d15-9f6d-8e1afa2ff68d", "text": "Ha a számjegyeinek összege osztható 3-mal", "isCorrect": true}, {"id": "802944e7-486a-461e-ad83-c6e6b45a500a", "text": "Ha 3-ra végződik", "isCorrect": false}, {"id": "89565c0b-a7e7-4073-91bb-1b349fcfe384", "text": "Ha páratlan", "isCorrect": false}, {"id": "211caa1c-93f1-43ee-bb7b-139e5d81cdfe", "text": "Ha az utolsó számjegye 3, 6 vagy 9", "isCorrect": false}], "timeLimit": 15}, {"id": "ef4fe037-a8c7-4284-80e7-9ff9ec7b742d", "text": "Mikor osztható egy szám 9-cel?", "type": "multiple-choice", "options": [{"id": "00e0aeaf-95e3-44f1-89ec-02dc4e2ac919", "text": "Ha a számjegyeinek összege osztható 9-cel", "isCorrect": true}, {"id": "2c9ae5de-30ce-4b80-94d0-99f3957d40c0", "text": "Ha 9-re végződik", "isCorrect": false}, {"id": "280d87ce-1f6e-456f-a0b7-fd2bf48ddf80", "text": "Ha 3-ra végződik", "isCorrect": false}, {"id": "4ab42f4a-d2f1-4e26-b8d8-4adbc52ced47", "text": "Ha páros", "isCorrect": false}], "timeLimit": 15}, {"id": "f2413c73-2ffd-494d-ad72-4ed1b728cb13", "text": "Mennyi a 243 számjegyeinek összege (2+4+3)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "9"}, {"id": "ceef0ed4-073b-4b4b-bebe-f7dbc611983f", "text": "A 243 osztható 3-mal és 9-cel is.", "type": "true-false", "options": [{"id": "e6b6cf42-396e-44ee-9794-6f70e68ef64b", "text": "Igaz", "isCorrect": true}, {"id": "6c4a85a9-9d0e-46a5-af1e-d247318892fe", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "e8281db5-d409-45e4-8c1a-d9918189fd30", "text": "Ha egy szám osztható 9-cel, akkor 3-mal is osztható.", "type": "true-false", "options": [{"id": "46a70d71-8ae7-41e8-b927-f7752120ab72", "text": "Igaz", "isCorrect": true}, {"id": "ae642e63-d295-407b-b197-10dcbc3084a2", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "25b2ef27-a61a-40be-9b8b-047a25642526", "text": "Osztható-e a 124 3-mal? (számjegyösszeg: 1+2+4=7)", "type": "true-false", "options": [{"id": "7828d54b-ef92-48c5-81e0-c24f79d50117", "text": "Igaz", "isCorrect": false}, {"id": "633af963-dc14-4649-b568-862db2ecf0b1", "text": "Hamis", "isCorrect": true}], "timeLimit": 15}, {"id": "bc71b309-a7ff-42a4-8546-1c8556b5cc77", "text": "Melyik számjegyet kell az X helyére írni a 51X számban, hogy osztható legyen 9-cel? (5+1+X=9)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "3"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('f16ab7d2-f0ec-46c4-bc66-c49fef9c6155', '21feff02-016d-46e2-bb9d-c27495133b1b', '19. óra: Oszthatóság 4-gyel és 100-zal', 'Oszthatósági szabály az utolsó két számjegy alapján.', 'Matematika', '6. osztály', 'Egész számok, oszthatóság', '[{"id": "01096fae-82b6-4c4d-93bc-07e609022729", "text": "Mikor osztható egy szám 4-gyel?", "type": "multiple-choice", "options": [{"id": "a4f49525-b5b9-4c20-9630-c9e6dea3d835", "text": "Ha az utolsó két számjegyéből képzett kétjegyű szám osztható 4-gyel (vagy 00)", "isCorrect": true}, {"id": "c0a4ef20-c6a8-4243-bd10-cbd97d3deea0", "text": "Ha 4-re végződik", "isCorrect": false}, {"id": "b8ae52be-1ff0-498d-b8d3-5b5b57bee27e", "text": "Ha a számjegyek összege 4", "isCorrect": false}, {"id": "e1d28a11-549c-42ad-b6fe-a9b8242dc561", "text": "Ha páros", "isCorrect": false}], "timeLimit": 15}, {"id": "b587db0d-afc9-4a66-bb78-142549eb8131", "text": "Mikor osztható egy szám 100-zal?", "type": "multiple-choice", "options": [{"id": "25b00c60-9b82-432d-98bc-38c27f55492f", "text": "Ha az utolsó két számjegye 00", "isCorrect": true}, {"id": "f4b2e8bd-6149-4493-b137-ad7a7c33baf8", "text": "Ha 100-ra végződik", "isCorrect": false}, {"id": "18784c82-3693-4c02-9f5f-3490ed55529c", "text": "Ha 0-ra végződik", "isCorrect": false}, {"id": "3f4df1e0-28a8-40da-99a0-7590c4fb4d64", "text": "Ha páros", "isCorrect": false}], "timeLimit": 15}, {"id": "ecb61bcd-4c8e-44cc-bcb5-226d89891383", "text": "A 316 osztható 4-gyel (mert 16 osztható 4-gyel).", "type": "true-false", "options": [{"id": "d595e680-beae-46fd-916f-21b1f309b8f8", "text": "Igaz", "isCorrect": true}, {"id": "47f28eb0-7b10-4267-bda6-9796d063a80f", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "3f3b21d1-5b2f-40a1-8579-095f52374405", "text": "A 7500 osztható 100-zal és 4-gyel is.", "type": "true-false", "options": [{"id": "c1c5d83a-02ea-401a-9640-5884315e97d0", "text": "Igaz", "isCorrect": true}, {"id": "d9f77ba6-ea2e-4f51-ab12-a6cf0b4854aa", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "b7d3c857-a3ac-4869-8819-c7ee0a45e19a", "text": "Osztható-e a 522 4-gyel? (22 / 4 = 5 maradék 2)", "type": "true-false", "options": [{"id": "e0e7c21f-c495-4c0c-a6c7-7e12e9dd5c67", "text": "Igaz", "isCorrect": false}, {"id": "a6bdd3a9-d4e6-42e4-a1d0-aadb3fa5f84c", "text": "Hamis", "isCorrect": true}], "timeLimit": 15}, {"id": "0fdcb473-5817-4767-9aa5-548168b6a135", "text": "Melyik legkisebb kétjegyű szám osztható 4-gyel?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "12"}, {"id": "89faa56c-4936-445f-b14f-1051edcf4d85", "text": "A 1000 osztható 4-gyel.", "type": "true-false", "options": [{"id": "908e85e0-bf68-4513-9ed4-456bcdb36302", "text": "Igaz (00-ra végződik)", "isCorrect": true}, {"id": "6f616581-8f6c-45ca-ad00-700b0452466a", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('e357bede-30e0-4a93-9be8-54677f0398a4', '21feff02-016d-46e2-bb9d-c27495133b1b', '20. óra: Összetett oszthatósági szabályok', 'Új oszthatósági szabályok alkotása (pl. 6-tal való oszthatóság).', 'Matematika', '6. osztály', 'Egész számok, oszthatóság', '[{"id": "f776894a-2229-4880-8820-6b79e79515f2", "text": "Mikor osztható egy szám 6-tal?", "type": "multiple-choice", "options": [{"id": "4b54e69d-7103-4b6b-81fa-dc11c2f745f6", "text": "Ha 2-vel és 3-mal is osztható egyszerre (páros és a számjegyösszeg 3-mal osztható)", "isCorrect": true}, {"id": "aae5623e-f424-444c-86c2-29a49f2d402e", "text": "Ha 6-ra végződik", "isCorrect": false}, {"id": "9c42fdf3-fe80-4e1b-aa52-cc0c89e6fdf2", "text": "Ha a számjegyek összege 6", "isCorrect": false}, {"id": "0f40360e-229f-4ba3-830f-19204498f975", "text": "Ha 12-vel osztható", "isCorrect": false}], "timeLimit": 15}, {"id": "1e4a7d41-a1f7-47b2-a4d0-29e7e6064686", "text": "Mikor osztható egy szám 15-tel?", "type": "multiple-choice", "options": [{"id": "78529a64-7439-47d8-bb63-1774bd5922f8", "text": "Ha 3-mal és 5-tel is osztható egyszerre", "isCorrect": true}, {"id": "4c9c2ea7-56c6-4012-93df-d1b76e6bc390", "text": "Ha 15-re végződik", "isCorrect": false}, {"id": "e4c66f68-0707-4a71-82e0-21c5fde0cc14", "text": "Ha páratlan", "isCorrect": false}, {"id": "59e9eeee-2cc0-4eaf-bdcd-27afe50a2311", "text": "Ha 5-tel osztható", "isCorrect": false}], "timeLimit": 15}, {"id": "aabc8c0d-604b-405d-b17a-e016f1e352e0", "text": "A 132 osztható 6-tal (páros és 1+3+2=6).", "type": "true-false", "options": [{"id": "5316d44f-2405-46ac-ae54-c8555c9297f0", "text": "Igaz", "isCorrect": true}, {"id": "62f6afe3-1e21-45da-ae21-a37266cf4439", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "8582b4db-c79f-4e19-b05e-a98f72e675b1", "text": "A 45 osztható 15-tel.", "type": "true-false", "options": [{"id": "15d78b11-b345-4c4a-b5a8-109841f50492", "text": "Igaz", "isCorrect": true}, {"id": "f5e441e0-d7ad-445e-b423-321117562548", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "3d434f35-47ba-4a5b-8839-9a68d34d7fd9", "text": "Mikor osztható egy szám 12-vel?", "type": "multiple-choice", "options": [{"id": "88f227ab-07c2-4c3b-917b-623edc259eba", "text": "Ha 3-mal és 4-gyel is osztható", "isCorrect": true}, {"id": "d4f48865-8362-4f43-baae-555939e50386", "text": "Ha 2-vel és 6-tal", "isCorrect": false}, {"id": "77b6ec9a-ba30-4a86-aa98-234609348ee0", "text": "Ha 12-re végződik", "isCorrect": false}, {"id": "c64bd20c-bb97-409d-bf9b-7e9a5a77a651", "text": "Ha páros", "isCorrect": false}], "timeLimit": 15}, {"id": "da958a24-8c27-44ac-adb7-456628ecde3d", "text": "Osztható-e a 210 6-tal?", "type": "true-false", "options": [{"id": "40522d05-02b9-42e4-b2a0-4dfc227f0762", "text": "Igaz (páros, 2+1+0=3)", "isCorrect": true}, {"id": "40b9def5-c33b-4b99-b7dd-7f801b19b3f2", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "14e44228-001d-4835-b434-6c88847dde07", "text": "Melyik számjegy tehető a 34_ végére, hogy osztható legyen 6-tal? (páros kell és 3+4+X osztható 3-mal)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('fbd07a87-a22f-457c-817f-d58a98208cac', '21feff02-016d-46e2-bb9d-c27495133b1b', '21. óra: Gyakorlóóra: a tanult oszthatósági szabályok alkalmazása', 'Gyakorlás, igaz-hamis állítások, halmazábrák oszthatóságra.', 'Matematika', '6. osztály', 'Egész számok, oszthatóság', '[{"id": "3354b6ab-a38b-4fde-a89d-fd98ca5ebc07", "text": "Melyik szám osztható 2-vel, 3-mal és 5-tel is (azaz 30-cal)?", "type": "multiple-choice", "options": [{"id": "f1565b24-c983-471f-8cc3-efd0a62d4c1e", "text": "90", "isCorrect": true}, {"id": "becf97bb-638f-4abe-b763-a244897f05bc", "text": "45", "isCorrect": false}, {"id": "d7f21bf8-b253-45cd-a695-0d5bc60de8a2", "text": "80", "isCorrect": false}, {"id": "43b8950f-e058-40c4-a6df-9e05faf098f5", "text": "100", "isCorrect": false}], "timeLimit": 15}, {"id": "6b195184-fdbc-4d7a-a89e-06253a8d5bf1", "text": "A 180 osztható 4-gyel és 9-cel is.", "type": "true-false", "options": [{"id": "bd5a7d08-a22d-46c3-ba37-93c3a4746e09", "text": "Igaz", "isCorrect": true}, {"id": "7329b4f4-e71f-4d56-baec-8b6494430119", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "191ee126-dbdf-4575-81e0-75f5ed088518", "text": "Hány olyan szám van 1 és 100 között, ami osztható 10-zel?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "fe0cbc3e-fdff-4366-b47a-a413f7dd9656", "text": "Melyik szám osztható 9-cel?", "type": "multiple-choice", "options": [{"id": "16aef040-591d-48dc-9510-3c0761b9c9c1", "text": "729 (7+2+9=18)", "isCorrect": true}, {"id": "cbbceeb1-94fc-48ae-b53a-91f8c884b925", "text": "721", "isCorrect": false}, {"id": "e51da854-e9f2-4a1c-94ac-49625159ee65", "text": "725", "isCorrect": false}, {"id": "cb440ecb-2446-4e3b-8186-be26d5f2912f", "text": "730", "isCorrect": false}], "timeLimit": 15}, {"id": "c2484923-fe50-4adb-ae34-07e33f8c0e55", "text": "Ha egy szám osztható 10-zel, akkor 5-tel is osztható.", "type": "true-false", "options": [{"id": "e6a268d8-b9a1-4188-a217-7f5fb74bd60b", "text": "Igaz", "isCorrect": true}, {"id": "6db24af2-c610-4ae7-a371-9b09cf2694e2", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "948ffeff-61a1-4d95-be50-676c8ac6d280", "text": "Melyik a legkisebb háromjegyű szám, ami osztható 5-tel?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "100"}, {"id": "6a5b6099-3b1e-4d82-b0d3-389e34249875", "text": "Melyik a legkisebb háromjegyű szám, ami osztható 3-mal?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "102"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('4a2a1631-de81-4639-8bf7-aa0b37469806', '21feff02-016d-46e2-bb9d-c27495133b1b', '22. óra: Többszörös, közös többszörös', 'Közös többszörösök, legkisebb közös többszörös (lkkt) és közös nevező.', 'Matematika', '6. osztály', 'Egész számok, oszthatóság', '[{"id": "4ebb26c4-e7be-4183-90e6-a5f705d786cd", "text": "Mit jelent két szám legkisebb közös többszöröse (lkkt)?", "type": "multiple-choice", "options": [{"id": "f5fef891-fa3e-4b04-9352-df36c8b09233", "text": "A legkisebb olyan pozitív számot, amely mindkét számmal osztható", "isCorrect": true}, {"id": "3b57a82d-0cf9-4e54-b855-b0937a2bfb8a", "text": "A két szám szorzatát mindig", "isCorrect": false}, {"id": "64221471-73dc-48a8-944b-d380c3a3707f", "text": "A legkisebb osztót", "isCorrect": false}, {"id": "890232a8-1737-4fc7-a839-47d49a33742d", "text": "A két szám különbségét", "isCorrect": false}], "timeLimit": 15}, {"id": "a75fe2f2-96d9-47b8-83a3-d34ddfa7ef3d", "text": "Mennyi a 4 és 6 legkisebb közös többszöröse, lkkt(4, 6)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "12"}, {"id": "d42fa5e2-4259-4f64-ac03-cc57e0f08971", "text": "Mennyi a 3 és 5 legkisebb közös többszöröse, lkkt(3, 5)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "15"}, {"id": "748027e1-316f-4650-8123-d05d5b2afadd", "text": "Relatív prímek (pl. 3 és 5) legkisebb közös többszöröse a két szám szorzata.", "type": "true-false", "options": [{"id": "4eaae780-7bc5-4cda-a6a0-ac9a7cf8470f", "text": "Igaz", "isCorrect": true}, {"id": "3ae5a43d-41c5-4cc0-9300-72466964108f", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "2677fb37-0ad4-4a5e-b87c-b2b7127e6858", "text": "A közös többszöröst használjuk törtek közös nevezőre hozásakor.", "type": "true-false", "options": [{"id": "35ed54cd-c400-4b59-8af9-bceb446c36fa", "text": "Igaz", "isCorrect": true}, {"id": "8139325c-b9a6-47e4-baba-d506fc3fa09b", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "18a4e1ad-c6e9-41fe-bcc9-6486594650dc", "text": "Mennyi a 6 és 8 legkisebb közös többszöröse?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "24"}, {"id": "6a50dab3-7709-4de3-8655-91e28d50de93", "text": "Melyik szám közös többszöröse a 2-nek és a 5-nek?", "type": "multiple-choice", "options": [{"id": "7047ac77-9cd7-4407-bc49-6b386b9ce765", "text": "10", "isCorrect": true}, {"id": "984a9223-66b6-4f8b-915b-32d0678a0aaf", "text": "15", "isCorrect": false}, {"id": "10b8b6bf-0bdd-4373-9855-3e100a83d8f8", "text": "8", "isCorrect": false}, {"id": "9b352471-e866-43e8-b845-89dcf9faee68", "text": "12", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('139367c5-823d-4183-8fb3-688699d25159', '21feff02-016d-46e2-bb9d-c27495133b1b', '23. óra: Osztó, közös osztó', 'Közös osztók, legnagyobb közös osztó (lnko) és törtek egyszerűsítése.', 'Matematika', '6. osztály', 'Egész számok, oszthatóság', '[{"id": "b5516b7c-4f2d-4ced-b125-a6f986711882", "text": "Mit jelent két szám legnagyobb közös osztója (lnko)?", "type": "multiple-choice", "options": [{"id": "00cd493d-2797-453d-8ce2-b9468c07697d", "text": "A legnagyobb olyan pozitív számot, amely mindkét számot osztja", "isCorrect": true}, {"id": "bcaacac8-6188-4338-a4ed-c14f70ad61bd", "text": "A két szám összege", "isCorrect": false}, {"id": "d5b9a489-ffb8-45d9-9ec7-fff60d66b757", "text": "A legkisebb többszöröst", "isCorrect": false}, {"id": "e753e3bf-c4b8-4451-bc7d-7067bf9a8533", "text": "Az 1-et mindig", "isCorrect": false}], "timeLimit": 15}, {"id": "59768128-77c4-4b76-b304-aa6358823c16", "text": "Mennyi a 12 és 18 legnagyobb közös osztója, lnko(12, 18)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "3da9b9f7-4ba4-4b81-a44d-9621fd4607f9", "text": "Mennyi a 15 és 25 legnagyobb közös osztója?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5"}, {"id": "4d296ec8-7f07-4feb-8585-9077395f38ec", "text": "Két számot relatív prímeknek nevezünk, ha a legnagyobb közös osztójuk 1.", "type": "true-false", "options": [{"id": "f1665ad3-c531-475a-bb93-46e59de77de4", "text": "Igaz", "isCorrect": true}, {"id": "2edbc86a-fbd7-46a8-aa89-88574c9400e3", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "3a4f65f5-5dab-4198-a1ba-d69e6bac8ca6", "text": "A 8 és 9 relatív prímek (lnko(8,9) = 1).", "type": "true-false", "options": [{"id": "3b1bbbd2-e81b-4218-b2bc-ffd11328c4a5", "text": "Igaz", "isCorrect": true}, {"id": "60d9f56a-9a45-4b29-b45f-ab80745258d8", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "863be4d1-d781-4904-bd64-6f36a5cacbd6", "text": "A legnagyobb közös osztóval egyszerűsítve a törtet a legegyszerűbb alakot kapjuk.", "type": "true-false", "options": [{"id": "dc25e1ad-2a51-484c-82fd-cc54f428b638", "text": "Igaz", "isCorrect": true}, {"id": "318b8fcb-3812-4d72-8518-eb0b71ae64dc", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "d30aa0e4-d39f-4832-95e0-aa201afde63e", "text": "Mennyi a 20 és 30 legnagyobb közös osztója?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('bb1e4c16-ea3a-45be-941b-10fa75277ef4', '21feff02-016d-46e2-bb9d-c27495133b1b', '24. óra: Összefoglalás', 'A tanult fogalmak ismétlése, rendszerezése az egész számok és oszthatóság témakörből.', 'Matematika', '6. osztály', 'Egész számok, oszthatóság', '[{"id": "213b7900-f71b-4cf6-8ec5-53248c91169f", "text": "Mennyi (-12) * (-5)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "60"}, {"id": "450c8a4e-c3f5-485d-8c19-8dd2c3c3b50b", "text": "Mennyi lkkt(6, 9)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "18"}, {"id": "846f4b3f-9205-408e-b9cd-2565e1c340d7", "text": "Mennyi lnko(24, 36)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "12"}, {"id": "77389d60-3505-43bc-bd0e-509b58340585", "text": "A 135 osztható 5-tel és 9-cel is.", "type": "true-false", "options": [{"id": "97d0773d-758a-4ea3-a9cd-14bfd91d4243", "text": "Igaz", "isCorrect": true}, {"id": "5bd07f82-0974-44e8-860c-1844ad596c6d", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "b39c7363-250f-4b46-9eed-ebfdb6eed4c8", "text": "A 2 az egyetlen páros prímszám.", "type": "true-false", "options": [{"id": "87410499-7a5b-40fb-9c23-f9def16abed8", "text": "Igaz", "isCorrect": true}, {"id": "1123a06c-dd4c-4ffc-9d6a-f6a0067795e1", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "9c67dbe9-8731-4543-a7dd-a5882187a32f", "text": "Mennyi (-50) : (+10)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-5"}, {"id": "17708fa5-b97c-4a22-94e2-ea6b2e0385a8", "text": "Melyik szám osztható 4-gyel?", "type": "multiple-choice", "options": [{"id": "39a87cc6-6d97-4446-8959-263350b01239", "text": "524", "isCorrect": true}, {"id": "79f7f92e-db19-4ed3-9c68-ea3712f5d1cd", "text": "522", "isCorrect": false}, {"id": "76ceb002-a7d1-4c87-b2aa-a2e72dd6c32b", "text": "521", "isCorrect": false}, {"id": "4a37e0af-5241-4276-8809-164e4fc17433", "text": "523", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('4939b38c-9ec7-4ca8-a3c1-8940a2549946', '21feff02-016d-46e2-bb9d-c27495133b1b', '25. óra: Tesztfeladatok megoldása', 'Feladatmegoldási gyakorlat önállóan az oszthatósági téma lezárása előtt.', 'Matematika', '6. osztály', 'Egész számok, oszthatóság', '[{"id": "31bf7d86-9d71-4f57-9706-a99212ace97f", "text": "Hány osztója van a 10-nek? (1, 2, 5, 10)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "1ff1078b-2e21-40c0-ba4c-36d00f3f53d7", "text": "Osztható-e a 432 6-tal?", "type": "true-false", "options": [{"id": "8f9673a4-e434-4b5b-b721-7bdba7a06cd3", "text": "Igaz (páros és 4+3+2=9)", "isCorrect": true}, {"id": "f823bd8c-b749-4bca-a1b7-468f132ecba0", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "0b5893dd-cd46-4f61-8f59-3ce32ee13acd", "text": "Mennyi (-7) * (+6)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-42"}, {"id": "e5593ecf-f07e-4941-913b-565ed6ee6119", "text": "Melyik szorzat eredménye pozitív?", "type": "multiple-choice", "options": [{"id": "325f14b3-c1af-412b-be29-2c27053aed48", "text": "(-4) * (-5)", "isCorrect": true}, {"id": "fc42804c-f0d6-45c0-b8f6-3749eba90608", "text": "(-4) * (+5)", "isCorrect": false}, {"id": "e85dcaef-fc3f-474e-9e66-1cf1a23a5e3d", "text": "(+4) * (-5)", "isCorrect": false}, {"id": "85b01a89-a76d-4153-a769-68a28517e609", "text": "(-4) * 0", "isCorrect": false}], "timeLimit": 15}, {"id": "4b4bac90-abdd-4fcb-bf66-b6b12534a214", "text": "Mennyi a maradék, ha 47-et 5-tel osztunk?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}, {"id": "1ec3b8a7-fece-46da-a80e-99db792a6111", "text": "A 17 prímszám.", "type": "true-false", "options": [{"id": "27b05368-923e-42ed-bee1-19baa71c6288", "text": "Igaz", "isCorrect": true}, {"id": "f584c24b-c3a4-4f64-9769-bc92b87d20a0", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "c19b384e-0fbb-4097-83f9-e99370eb0b69", "text": "Mennyi lkkt(4, 10)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('ff68e7e0-fb77-41c9-9a53-4a986c37980f', '21feff02-016d-46e2-bb9d-c27495133b1b', '26. óra: Témazáró dolgozat', 'Témazáró számonkérés az Egész számok és oszthatóság témakörből (10 kérdés).', 'Matematika', '6. osztály', 'Egész számok, oszthatóság', '[{"id": "e58439cd-7663-4093-b347-3e6bbffad867", "text": "1. Mennyi (-18) + (+30)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "12"}, {"id": "1fff693a-fce1-4498-9619-131c3c698fd6", "text": "2. Mennyi (-7) * (-9)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "63"}, {"id": "5a58216b-dbfd-4696-93e6-db7cdc595971", "text": "3. Mennyi (-72) : (+8)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-9"}, {"id": "e34c709a-64be-4035-ae83-f767979d3b98", "text": "4. Osztható-e a 534 3-mal?", "type": "true-false", "options": [{"id": "fe8639cd-6a63-4639-aa84-240407abcae3", "text": "Igaz (5+3+4=12)", "isCorrect": true}, {"id": "9d64676b-66c0-4ca9-84a0-5889d9403114", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "ed3dfeea-6d18-4308-a8a3-e501388e7f13", "text": "5. Osztható-e a 620 4-gyel?", "type": "true-false", "options": [{"id": "4a0f9ae0-69f4-4879-9a9c-d808ca22819f", "text": "Igaz (20 osztható 4-gyel)", "isCorrect": true}, {"id": "7290d610-0c36-46ea-b105-24e85314db4e", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "c4fc1fd9-5bef-470e-9f08-307d1d8ef35c", "text": "6. Mennyi lkkt(6, 10)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}, {"id": "6626d77a-e74d-48d7-a642-2bfa03c71f6f", "text": "7. Mennyi lnko(18, 24)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "1d783878-b10f-436e-8666-938836a11c0c", "text": "8. Hány prímszám van 1 és 10 között? (2, 3, 5, 7)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "2ac6a451-3eb5-43a4-841f-02eb1a2f010e", "text": "9. Hányféleképpen ülhet le 3 gyermek 3 székre?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "c8c621c9-049f-4839-b4e6-b03046da8f98", "text": "10. Két negatív szám szorzata mindig pozitív.", "type": "true-false", "options": [{"id": "b2bc06c1-46ef-44b4-8cab-f003ddcbe1d9", "text": "Igaz", "isCorrect": true}, {"id": "e653ae71-d8f8-4da0-987b-534caf9acb47", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('ec919c27-64a0-444e-a82b-9143d51060fa', '21feff02-016d-46e2-bb9d-c27495133b1b', '27. óra: Témazáró dolgozat értékelése', 'A témazáró dolgozat megbeszélése, hibák elemzése, tapasztalatok összegzése.', 'Matematika', '6. osztály', 'Egész számok, oszthatóság', '[{"id": "86b5660c-30d7-41d1-abd0-777e1e0e20ed", "text": "Mi volt a leggyakoribb hiba az előjelszabályok alkalmazásakor?", "type": "multiple-choice", "options": [{"id": "311391fc-4f47-4bee-8ad2-2f64b7830955", "text": "A szorzás/osztás és összeadás előjelszabályainak összetévesztése", "isCorrect": true}, {"id": "013bcf4d-e6d9-44ae-b91c-8c90b14a8b65", "text": "A számok leírása", "isCorrect": false}, {"id": "5c9b5548-3ac1-4754-831d-70faab4f4f83", "text": "A vonalzó használata", "isCorrect": false}, {"id": "8a12f527-d3ec-4243-95bc-c5a329233e07", "text": "A válasz elhagyása", "isCorrect": false}], "timeLimit": 15}, {"id": "2b70ed63-8155-44d9-8452-899d4eebbbc8", "text": "Az osztási szabályok (pl. 3-mal, 9-cel) esetén a számjegyek összege a döntő.", "type": "true-false", "options": [{"id": "21c150ab-9c7f-4349-b25e-4d8334222a10", "text": "Igaz", "isCorrect": true}, {"id": "9586546c-dc21-46e7-81f4-3d9b6a3e9a0e", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "6777e30c-3de1-4679-9b1f-940144a71776", "text": "Mennyi (-5) * (-5)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "25"}, {"id": "fb00a235-f1c7-4a75-976b-a6171b50686c", "text": "A lkkt meghatározásánál a többszörösök közül a legkisebbet választjuk.", "type": "true-false", "options": [{"id": "d5cabd9c-47cc-49b2-a28e-e60b34174369", "text": "Igaz", "isCorrect": true}, {"id": "37938855-f196-441f-93b5-6c4846dda6d8", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "2127ba0d-5947-4a68-a527-df6f6ea74515", "text": "Mennyi (-30) : (-5)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "c16b5d97-0391-4007-a5b5-f4a00bc00dda", "text": "A dolgozatok áttekintése segít a hiányosságok pótlásában.", "type": "true-false", "options": [{"id": "d66beaf7-1121-43ef-a259-a922e64e4994", "text": "Igaz", "isCorrect": true}, {"id": "7a8e8a2c-ec1d-4f39-829e-d5aaeb9b2122", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "e7040702-55a4-4626-bdf7-c7bcd82a4af2", "text": "Mennyi lnko(10, 15)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('f68d48d8-7287-473f-9f8b-c34ba12c0409', '21feff02-016d-46e2-bb9d-c27495133b1b', '28. óra: Mit tanultunk a törtekről? Ismétlés', 'Ötödikben tanult ismeretek: közönséges tört értelmezése, számláló, nevező, bővítés, egyszerűsítés.', 'Matematika', '6. osztály', 'Törtek', '[{"id": "6bea52c0-4ee9-4f4d-a3fb-95320110e0cf", "text": "Mi a közönséges tört felső száma?", "type": "multiple-choice", "options": [{"id": "cc9d45ca-8767-4fd4-944a-bbb32f6bd949", "text": "Számláló", "isCorrect": true}, {"id": "197cf6a9-b589-471e-89f9-5468f946ddc6", "text": "Nevező", "isCorrect": false}, {"id": "ffb9d2c9-a2b0-42e1-b084-d09b319c2a01", "text": "Törtvonal", "isCorrect": false}, {"id": "67cfa8b0-cf1d-46da-b969-a3b6ba02423c", "text": "Egész rész", "isCorrect": false}], "timeLimit": 15}, {"id": "4506c3e8-38af-4d4a-b39d-42b634e1c5d0", "text": "Mi a közönséges tört alsó száma?", "type": "multiple-choice", "options": [{"id": "b105188d-13f2-4286-8a2c-7341c9e3d0de", "text": "Nevező", "isCorrect": true}, {"id": "ae62aa7b-40b1-43e4-a209-7534916e47cd", "text": "Számláló", "isCorrect": false}, {"id": "18dcaf15-b97e-4f10-a6da-f91ab2e45529", "text": "Osztó", "isCorrect": false}, {"id": "4d60837f-d0f6-49f9-bdc0-6783619773b5", "text": "Különbség", "isCorrect": false}], "timeLimit": 15}, {"id": "034784cb-bee0-4d34-9297-aedc6b5b3f51", "text": "Mennyi a 3/4 bővítve 2-vel?", "type": "multiple-choice", "options": [{"id": "6740d20d-fef0-4c08-b0f6-c9fa3e63dcf4", "text": "6/8", "isCorrect": true}, {"id": "6fe57de1-3128-44ee-bda6-40e321eed9dd", "text": "5/6", "isCorrect": false}, {"id": "7af97475-d886-4f0e-903d-9f1c5bd57455", "text": "3/8", "isCorrect": false}, {"id": "872ba8f5-9ef0-480a-a44c-417a5e74a685", "text": "6/4", "isCorrect": false}], "timeLimit": 15}, {"id": "2bbfce1f-9b95-4304-acd9-dd159137fb90", "text": "Mennyi a 6/10 egyszerűsítve 2-vel?", "type": "multiple-choice", "options": [{"id": "935bdf60-0176-4334-8e13-730a48564475", "text": "3/5", "isCorrect": true}, {"id": "21108cd5-a28c-481a-ac26-34380447128c", "text": "3/10", "isCorrect": false}, {"id": "a7318b58-15dd-4432-89bc-e56c570ca9b3", "text": "6/5", "isCorrect": false}, {"id": "9a1a7173-1b81-4ff0-bd07-cb0e4d9c015c", "text": "1/2", "isCorrect": false}], "timeLimit": 15}, {"id": "7359c4d8-afb4-4336-8a0e-83a05dbab8a8", "text": "A tört értéke nem változik, ha számlálóját és nevezőjét ugyanazzal a nem-nulla számmal szorozzuk (bővítjük).", "type": "true-false", "options": [{"id": "751ebcbd-3764-4335-8330-e213b85606fd", "text": "Igaz", "isCorrect": true}, {"id": "a3cbb6bb-2fb9-4bd1-94e5-7ceb13437fcf", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "ceb2fdca-942b-47eb-9145-85cb4cf29ff9", "text": "Hány negyedből áll 1 egész?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "9332c6a6-f253-4310-b9e0-2dda8f94bd86", "text": "Mennyi 1/2 + 1/4?", "type": "multiple-choice", "options": [{"id": "c8d84bbd-384c-4a3b-9cc0-445dcd0a9c69", "text": "3/4 (2/4 + 1/4)", "isCorrect": true}, {"id": "618112d0-0af6-41dc-bd40-339a2b5320d5", "text": "2/6", "isCorrect": false}, {"id": "63467529-bdd7-46b2-b9bf-3ea007e61cef", "text": "2/4", "isCorrect": false}, {"id": "44ae19e5-a9dc-49d0-bb64-12a31c4c318b", "text": "1/6", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('dca1bbcc-3afc-43da-8937-dd815f1e1444', '21feff02-016d-46e2-bb9d-c27495133b1b', '29. óra: Mit tanultunk a törtekről? Ismétlés II.', 'Összeadás és kivonás azonos és különböző nevezőjű törtekkel.', 'Matematika', '6. osztály', 'Törtek', '[{"id": "d6079039-6da7-4ca5-a196-d8d3ade26411", "text": "Hogyan adjuk össze a különböző nevezőjű törteket?", "type": "multiple-choice", "options": [{"id": "09a0866d-f4cf-4f1d-ac7b-d931949b2fa7", "text": "Közös nevezőre hozzuk őket, majd a számlálókat összeadjuk", "isCorrect": true}, {"id": "7a4c43d3-b7c7-472c-b2f5-46295d152c1a", "text": "A számlálókat és nevezőket is összeadjuk", "isCorrect": false}, {"id": "ebca401c-7349-4bf4-bab0-a93ace4a79ed", "text": "A számlálókat megszorozzuk", "isCorrect": false}, {"id": "561cad39-a786-4326-a7da-3dc3d060df31", "text": "Nem lehet összeadni őket", "isCorrect": false}], "timeLimit": 15}, {"id": "a1073104-f5c4-43b7-9825-7c95084032e7", "text": "Mennyi 1/3 + 1/6? (2/6 + 1/6)", "type": "multiple-choice", "options": [{"id": "064f73d3-3304-4c10-88a3-a28d034eb09e", "text": "3/6 (azaz 1/2)", "isCorrect": true}, {"id": "d635456f-17de-40a5-ab05-d7d233f3d342", "text": "2/9", "isCorrect": false}, {"id": "1ceef29f-c72b-4f4a-be11-007f8b6fa80a", "text": "1/9", "isCorrect": false}, {"id": "c3e272ca-d51c-471c-8b5a-571ded86ec95", "text": "2/6", "isCorrect": false}], "timeLimit": 15}, {"id": "9612a3c7-7f24-4ace-8f83-e9c2a104d410", "text": "Mennyi 5/8 - 3/8?", "type": "multiple-choice", "options": [{"id": "070b1064-2a6f-4738-ae4e-966b4637ddbe", "text": "2/8 (azaz 1/4)", "isCorrect": true}, {"id": "4362d5d1-d82f-4bbe-b630-89ea49493882", "text": "2/0", "isCorrect": false}, {"id": "78f2587f-064f-4b93-b4cd-bef5e7d82aa9", "text": "8/8", "isCorrect": false}, {"id": "ecdd1bf6-0321-46b8-bc69-cb638827c7d5", "text": "1/8", "isCorrect": false}], "timeLimit": 15}, {"id": "24a88d4b-1e5c-4c2d-9468-e962d7e18f1b", "text": "Az 1/2 és 2/4 egyenlő értékű törtek.", "type": "true-false", "options": [{"id": "f6aa5b7c-8785-4947-a447-85f9f44bb2ec", "text": "Igaz", "isCorrect": true}, {"id": "011af1ff-63a2-45da-852b-d2ca6f057d62", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "75c6e032-9eef-4f45-8f29-256a57c5e1ef", "text": "Hány nyolcad van 3/4-ben?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "4785cdb1-77e7-46c8-bea9-659bfbaf28d6", "text": "Mennyi 1 egészből kivonva 2/5-öt?", "type": "multiple-choice", "options": [{"id": "8b840340-059f-4c15-8b04-323e5ea2a07d", "text": "3/5", "isCorrect": true}, {"id": "40b3dca2-6a98-4ad9-878f-98aa555c8853", "text": "1/5", "isCorrect": false}, {"id": "f9a1d914-0bd2-4a70-b452-d48e1863a436", "text": "2/5", "isCorrect": false}, {"id": "d1f77ea4-9a60-4eab-a7b3-cf74b480e2da", "text": "5/5", "isCorrect": false}], "timeLimit": 15}, {"id": "175abf3f-b71f-4e47-8a49-386f517ea226", "text": "A törtvonal osztás műveletet jelent.", "type": "true-false", "options": [{"id": "d4796e10-2171-44da-91be-45fce4c8a4a6", "text": "Igaz", "isCorrect": true}, {"id": "0ad22d92-0ab7-41e4-9344-8abf062a8311", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());